#!/usr/bin/env python3
"""Generate the CORE.STO.CACHE fixtures (AC-1, AC-2, key names). CC-BY-4.0 test data.

Everything here is computed from the leaf spec's rules with Python's hashlib and json, never
by running the Rust crate. Fixed seed; the output is byte-identical on every run.

key_names.txt
    Cache keys and the item file name each must get: the SHA-256 (hex) of the key's canonical
    JSON (RFC 8785; for ASCII strings this is json.dumps with sorted keys and no spaces).
    Integers are decimal strings (fid-canon project rule). Fields:
      memo:     args_digest, command, input_digests, kernel_digest, key, kind, major
      snapshot: entry_hash, format, key, kind
    with key = "fid-cache-key@1".
    Lines: memo <command> <major> <args> <kernel> <inputs joined by , or -> <name>
           snapshot <entry_hash> <format> <name>

session_200/session.txt and session_200.state_digest (AC-1)
    A test-kit session of 200 commits of command test.step@1. Every commit's result is a pure
    function of its arguments digest and the state before it, so it can be memoised under
    Memo{test.step, 1, args, [state before], kernel}; after commits 100 and 200 a snapshot of
    the state is cached under Snapshot{entry hash, 1}. The model (all values are sha256: wire
    strings, hashed as ASCII):
      s0      = H("session-200 genesis")
      a_i     = H("session-200 args <i>")
      r_i     = H("result\\n" + a_i + "\\n" + s_(i-1))       memoised result (its wire bytes)
      s_i     = H(s_(i-1) + "\\n" + r_i)                     state after commit i
      e_i     = H("session-200 entry <i>\\n" + a_i)          journal entry hash of commit i
    session_200.state_digest holds s_200 and a newline.

lru_expected.json (AC-2)
    Limit 1 MiB; 50 items of 64 KiB (item i: 65536 bytes of value i) under
    Snapshot{H("lru item <i>"), 1}; a fixed op sequence from a seeded LCG. Every stored item
    costs its file size: a 161-byte header ("fid-cache-item@1\\n", key digest line, content
    digest line) plus the content, so at most 15 items fit. Every put and every hit takes the
    next value of a monotonic access counter; after a put, the item with the smallest counter
    is evicted until the total is at most the limit. Expected: the get outcomes in order, the
    remaining items (sorted) and their order from least to most recently used.

Run:  python fixtures/core/sto/cache/make_fixtures.py [--check]
"""

import hashlib
import json
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
KEY_FORMAT = "fid-cache-key@1"
HEADER_LEN = len(b"fid-cache-item@1\n") + 72 + 72


def H(text):
    return "sha256:" + hashlib.sha256(text.encode("ascii")).hexdigest()


def canonical(obj):
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("ascii")


def memo_name(command, major, args, inputs, kernel):
    obj = {"args_digest": args, "command": command, "input_digests": list(inputs),
           "kernel_digest": kernel, "key": KEY_FORMAT, "kind": "memo", "major": str(major)}
    return hashlib.sha256(canonical(obj)).hexdigest()


def snap_name(entry, fmt):
    obj = {"entry_hash": entry, "format": str(fmt), "key": KEY_FORMAT, "kind": "snapshot"}
    return hashlib.sha256(canonical(obj)).hexdigest()


outputs = {}

# ------------------------------------------------------------------ key names
lines = ["# CORE.STO.CACHE key file names, generated by make_fixtures.py. CC-BY-4.0."]
for n, (cmd, major, inputs) in enumerate([("test.step", 1, 1), ("align.run_bestfit", 3, 0),
                                          ("x", 99999, 3), ("geo.fit_plane", 1, 2)]):
    args = H(f"keys args {n}")
    kernel = H(f"keys kernel {n}")
    ins = [H(f"keys input {n} {k}") for k in range(inputs)]
    joined = ",".join(ins) if ins else "-"
    lines.append(f"memo {cmd} {major} {args} {kernel} {joined} {memo_name(cmd, major, args, ins, kernel)}")
for n, fmt in enumerate([1, 2, 4294967295]):
    entry = H(f"keys entry {n}")
    lines.append(f"snapshot {entry} {fmt} {snap_name(entry, fmt)}")
outputs["key_names.txt"] = "\n".join(lines) + "\n"

# ------------------------------------------------------------------ session_200 (AC-1)
kernel = H("session-200 kernel manifest")
s = H("session-200 genesis")
lines = ["# CORE.STO.CACHE AC-1 session, generated by make_fixtures.py. CC-BY-4.0.",
         "# command <name> <major> | kernel <digest> | genesis <state> |",
         "# commit <i> <args digest> <entry hash> | snapshot <entry hash> <format>",
         "command test.step 1", f"kernel {kernel}", f"genesis {s}"]
for i in range(1, 201):
    a = H(f"session-200 args {i}")
    r = H("result\n" + a + "\n" + s)
    s = H(s + "\n" + r)
    e = H(f"session-200 entry {i}\n" + a)
    lines.append(f"commit {i} {a} {e}")
    if i in (100, 200):
        lines.append(f"snapshot {e} 1")
outputs["session_200/session.txt"] = "\n".join(lines) + "\n"
outputs["session_200.state_digest"] = s + "\n"

# ------------------------------------------------------------------ LRU (AC-2)
LIMIT = 1024 * 1024
ITEM = 64 * 1024
state = 2026


def rand(n):
    global state
    state = (state * 6364136223846793005 + 1442695040888963407) % (1 << 64)
    return (state >> 33) % n


ops = []
for i in range(50):
    ops.append(f"put {i}")
    for _ in range(2):
        ops.append(f"get {rand(i + 1)}")
for _ in range(40):
    k = rand(50)
    ops.append(f"put {k}" if rand(4) == 0 else f"get {k}")

items = {}  # index -> (size, tick)
tick = 0
gets = []
for op in ops:
    verb, i = op.split()
    i = int(i)
    if verb == "put":
        items[i] = (HEADER_LEN + ITEM, tick)
        tick += 1
        while sum(sz for sz, _ in items.values()) > LIMIT:
            oldest = min(items, key=lambda k: items[k][1])
            del items[oldest]
    else:
        if i in items:
            items[i] = (items[i][0], tick)
            tick += 1
            gets.append(True)
        else:
            gets.append(False)
order = sorted(items, key=lambda k: items[k][1])
expected = {"limit": LIMIT, "item_size": ITEM, "header": HEADER_LEN, "ops": ops, "gets": gets,
            "remaining": sorted(items), "lru_order": order}
outputs["lru_expected.json"] = json.dumps(expected, indent=1) + "\n"

# ------------------------------------------------------------------ write or check
stale = []
for rel, text in outputs.items():
    path = HERE / rel
    data = text.encode("ascii")
    if "--check" in sys.argv:
        if not path.exists() or path.read_bytes() != data:
            stale.append(rel)
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
if stale:
    print("stale:", ", ".join(stale))
    sys.exit(1)
print(f"{len(outputs)} files; lru keeps {len(order)} items; state {s}")
